import{_ as l,a0 as d,w as n,s as r,I as t,x as i,a1 as o,A as e,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Fedora Linux 上安装 Discord | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora Linux 上安装 Discord | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora Linux 上安装 Discord | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora Linux 上安装 Discord | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211120 How to Install Discord on Fedora Linux","title":"如何在 Fedora Linux 上安装 Discord","tag":"202111","desc":""},"relativePath":"202111/20211120 How to Install Discord on Fedora Linux.md","filePath":"[post].md"}'),u={name:"202111/20211120 How to Install Discord on Fedora Linux.md"};function h(c,s,g,k,f,b){const a=d("Link");return n(),r("div",null,[s[17]||(s[17]=t("h1",{id:"如何在-fedora-linux-上安装-discord",tabindex:"-1"},[i("如何在 Fedora Linux 上安装 Discord "),t("a",{class:"header-anchor",href:"#如何在-fedora-linux-上安装-discord","aria-label":"Permalink to “如何在 Fedora Linux 上安装 Discord”"},"​")],-1)),s[18]||(s[18]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/27/115501g3oiuirvzk4nvu3k.jpg",alt:""})],-1)),t("p",null,[o(a,{href:"https://discord.com/"},{default:e(()=>[...s[0]||(s[0]=[i("Discord",-1)])]),_:1}),s[1]||(s[1]=i(" 是一个流行的消息收发应用，可用于文字和语音信息传递。",-1))]),s[19]||(s[19]=p('<p>它是一些社区的福音，可以帮助他们扩大项目，接触更多的人，并维持一个粉丝和关注者的社区。而 Discord 最初是为游戏玩家设计的，这很令人惊讶。</p><p>Discord 可用于各种平台，包括 Linux。在本教程中，我将引导你完成在 Fedora 中安装 Discord 的步骤。</p><ul><li>使用 DNF 和 RPM Fusion 仓库安装 Discord</li><li>通过 Flatpak 安装Discord</li></ul><p>Flatpak 软件包是沙盒的，因此需要更多的磁盘空间和时间来启动。然而，他们会相当快地更新到新的版本。</p><p>无论你想使用 Flatpak 还是 DNF，选择权在你手上。我将向你展示这两种方法。</p><blockquote><p>非 FOSS 警报！</p><p>Discord 并不是开源的。但由于他们提供了一个 Linux 客户端，而且许多 Linux 用户都依赖它，所以我们会在这里介绍它。</p></blockquote><h3 id="方法-1-通过-rpm-fusion-仓库安装-discord" tabindex="-1">方法 1：通过 RPM Fusion 仓库安装 Discord <a class="header-anchor" href="#方法-1-通过-rpm-fusion-仓库安装-discord" aria-label="Permalink to “方法 1：通过 RPM Fusion 仓库安装 Discord”">​</a></h3><p>Discord 可以通过添加非自由的 RPM Fusion 仓库来安装，这是大多数 Fedora 用户的首选方法，因为更新很容易，而且应用的启动速度比 Flatpak 版本快。</p><p>打开终端，使用下面的命令来添加 RPM-fusion 非自由仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install https://download1.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>完成后，更新仓库列表（应该不需要，但只是为了它）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf update</span></span></code></pre></div><p>然后通过 <code>dnf</code> 命令安装 Discord，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install discord</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/install-discord-dnf.png?resize=800%2C525&amp;ssl=1" alt="Installing Discord using DNF"></p><p>如果被要求导入 GPG 密钥，只要按 <code>Y</code> 就可以授权了。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/authorize-gpg-key-1.png?resize=800%2C573&amp;ssl=1" alt="Authorize GPG key"></p><p>这就完成了！现在你可以从应用菜单中启动 Discord。你的登录页面将看起来像这样：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/Discord-2.png?resize=800%2C432&amp;ssl=1" alt="Launch Discord application"></p><h4 id="通过-dnf-删除-discord" tabindex="-1">通过 DNF 删除 Discord <a class="header-anchor" href="#通过-dnf-删除-discord" aria-label="Permalink to “通过 DNF 删除 Discord”">​</a></h4><p>如果你不想再使用 Discord，你可以从你的系统中删除它。要做到这一点，在终端运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf remove discord</span></span></code></pre></div><p>这真的很简单，不是吗？还有一种简单的安装 Discord 的方法，那就是使用 Flatpak 软件包。</p><h3 id="方法-2-通过-flatpak-安装-discord" tabindex="-1">方法 2：通过 Flatpak 安装 Discord <a class="header-anchor" href="#方法-2-通过-flatpak-安装-discord" aria-label="Permalink to “方法 2：通过 Flatpak 安装 Discord”">​</a></h3><p>Discord 可以使用 Flatpak 轻松安装，因为它在 Fedora 中是默认可用的。</p><p>首先，你需要在 Fedora 中启用 Flatpak 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span></code></pre></div><p>接下来，通过这个命令安装 Discord：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install discord</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/install-discord-flatpak.png?resize=800%2C545&amp;ssl=1" alt="Install Discord via Flatpak"></p><p>如果你想删除 Discord，那么只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak remove discord</span></span></code></pre></div><p>这就超级简单了。如果你在 Fedora Linux 上安装 Discord 需要任何帮助，请告诉我。</p><hr>',34)),t("p",null,[s[3]||(s[3]=i("via: ",-1)),o(a,{href:"https://itsfoss.com/install-discord-fedora/"},{default:e(()=>[...s[2]||(s[2]=[i("https://itsfoss.com/install-discord-fedora/",-1)])]),_:1})]),t("p",null,[s[8]||(s[8]=i("作者：",-1)),o(a,{href:"https://itsfoss.com/author/pranav/"},{default:e(()=>[...s[4]||(s[4]=[i("Pranav Krishna",-1)])]),_:1}),s[9]||(s[9]=i(" 选题：",-1)),o(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[5]||(s[5]=[i("lujun9972",-1)])]),_:1}),s[10]||(s[10]=i(" 译者：",-1)),o(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[6]||(s[6]=[i("geekpi",-1)])]),_:1}),s[11]||(s[11]=i(" 校对：",-1)),o(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[7]||(s[7]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=i("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[12]||(s[12]=[i("LCTT",-1)])]),_:1}),s[15]||(s[15]=i(" 原创编译，",-1)),o(a,{href:"https://linux.cn/"},{default:e(()=>[...s[13]||(s[13]=[i("Linux中国",-1)])]),_:1}),s[16]||(s[16]=i(" 荣誉推出",-1))])])}const F=l(u,[["render",h]]);export{x as __pageData,F as default};
